package com.example.xposedmodule;

import android.util.Log;
import androidx.annotation.NonNull;
import io.github.libxposed.api.XposedModule;
import io.github.libxposed.api.XposedInterface.Invoker;

public class ModuleMain extends XposedModule {
    private static final String TAG = "ModuleMain";

    @Override
    public void onPackageReady(@NonNull PackageReadyParam param) {
        try {
            Class<?> targetClass = Class.forName("com.target.app.MainActivity", true, param.getClassLoader());
            var targetMethod = targetClass.getDeclaredMethod("someMethod", String.class);

            hook(targetMethod).intercept(chain -> {
                log(Log.INFO, TAG, "Intercepted: " + chain.getExecutable().getName());
                String originalArg = (String) chain.getArg(0);

                // Modify arguments or execute original
                Object result = chain.proceed();

                // Return result
                return result;
            });
        } catch (Throwable t) {
            log(Log.ERROR, TAG, "Hook initialization failed", t);
        }
    }
}

templates.kotlin_module_example:
package com.example.xposedmodule

import android.util.Log
import io.github.libxposed.api.XposedModule

class ModuleMainKt : XposedModule() {
    companion object {
        const val TAG = "ModuleMainKt"
    }

    override fun onPackageReady(param: PackageReadyParam) {
        if (!param.isFirstPackage) return

        try {
            val targetClass = Class.forName("com.target.app.MainActivity", true, param.classLoader)
            val targetMethod = targetClass.getDeclaredMethod("someMethod", String::class.java)

            hook(targetMethod).intercept { chain ->
                log(Log.INFO, TAG, "Intercepted from Kotlin: ${chain.executable.name}")
                chain.proceed()
            }
        } catch (t: Throwable) {
            log(Log.ERROR, TAG, "Hook failed", t)
        }
    }
}
